const input = $input.first().json;
const body = input.body ?? input;
const order = body.order ?? body;
const orderId = order.id ?? order.order_id;
if (orderId === undefined || orderId === null || String(orderId).trim() === '') {
  throw new Error('Missing order id: provide id or order_id.');
}
const rawItems = order.line_items ?? order.items;
if (!Array.isArray(rawItems) || rawItems.length === 0) {
  throw new Error('Missing line items: provide a non-empty line_items array.');
}
const threshold = Number(body.low_stock_threshold ?? 5);
if (!Number.isFinite(threshold) || threshold < 0) {
  throw new Error('low_stock_threshold must be a non-negative number.');
}
const orderKey = 'woocommerce-order:' + String(orderId);
return rawItems.map((item, index) => {
  const productId = item.product_id ?? item.id;
  const quantity = Number(item.quantity ?? 1);
  const stockValue = item.stock_quantity;
  const stockQuantity = stockValue === null || stockValue === undefined ? null : Number(stockValue);
  if (productId === undefined || productId === null) throw new Error('Missing product_id for line item index ' + index);
  if (!Number.isFinite(quantity) || quantity <= 0) throw new Error('Invalid quantity for product ' + productId);
  if (stockQuantity !== null && (!Number.isFinite(stockQuantity) || stockQuantity < 0)) throw new Error('Invalid stock_quantity for product ' + productId);
  let status;
  if (stockQuantity === null) status = 'STOCK_UNKNOWN';
  else if (stockQuantity < quantity) status = 'OUT_OF_STOCK';
  else if ((stockQuantity - quantity) <= threshold) status = 'LOW_STOCK';
  else status = 'OK';
  return { json: {
    order_id: String(orderId),
    order_key: orderKey,
    line_item_index: index,
    product_id: String(productId),
    product_name: item.name ?? item.product_name ?? 'Unnamed product',
    requested_quantity: quantity,
    available_stock: stockQuantity,
    low_stock_threshold: threshold,
    inventory_status: status,
    alert_required: status === 'LOW_STOCK' || status === 'OUT_OF_STOCK' || status === 'STOCK_UNKNOWN',
    processing_mode: 'demo-payload-stock',
    note: 'Demo only: stock_quantity came from the webhook payload; no live WooCommerce API lookup or persistent duplicate check was performed.'
  }};
});
